// @luvallplay/ui: design tokens. Two sets:
// - luvallplay: the platform brand (Court Green, Smash Lime, Rally Coral, Net Navy);
// - threeWolves: the Three Wolves club theme the site uses today.
// tokens.css carries the brand as --lp-* custom properties (light, and dark
// under [data-theme="dark"]); it's generated by brandCss() and checked by a test.

import { luvallplay } from "./luvallplay.ts";

export { luvallplay, type BrandColor, type BrandTheme } from "./luvallplay.ts";
export { threeWolves, threeWolvesCssVars } from "./three-wolves.ts";

/** The brand as CSS: every token as --lp-<name>, light on :root, dark under [data-theme="dark"]. */
export function brandCss(): string {
  const b = luvallplay;
  const light: string[] = [];
  const dark: string[] = [];
  for (const [name, v] of Object.entries(b.color)) {
    light.push(`  --lp-${name}: ${v.light};`);
    if (v.dark !== v.light) dark.push(`  --lp-${name}: ${v.dark};`);
  }
  for (const [name, v] of Object.entries(b.font)) light.push(`  --lp-font-${name}: ${v};`);
  for (const [name, v] of Object.entries(b.space)) light.push(`  --lp-${name}: ${v};`);
  for (const [name, v] of Object.entries(b.radius)) light.push(`  --lp-${name}: ${v};`);
  return [
    "/* Luvallplay brand tokens: generated from packages/ui/src/luvallplay.ts by brandCss(). Don't edit by hand. */",
    ":root {",
    ...light,
    "}",
    "",
    '[data-theme="dark"] {',
    ...dark,
    "}",
    "",
  ].join("\n");
}
